func TestFileHeader(t *testing.T) {
	jst := time.FixedZone("JST", 9*60*60)
	now := time.Date(2026, 11, 4, 19, 12, 33, 999_000_000, jst)

	cases := []struct {
		name   string
		opts   Options
		params string
	}{
		{
			name: "defaults",
			opts: Options{},
			params: "//\tmerge: \"overwrite\"\n//\tmerge_nested: \"recursive\"\n" +
				"//\toption_file: null\n//\tpackage_option_file: null",
		},
		{
			name: "set",
			opts: Options{
				Merge:       MergeAppend,
				MergeNested: MergeNestedOverwrite,
				Loaded: &LoadedOptions{
					Files: []string{"kama/partial.yaml"},
					PackageFiles: map[string]string{
						"example.invalid/other": "other/kama_partial.yaml",
						"example.invalid/x":     "x/kama_partial.yaml",
					},
				},
			},
			params: "//\tmerge: \"append\"\n//\tmerge_nested: \"overwrite\"\n" +
				"//\toption_file: \"kama/partial.yaml\"\n" +
				"//\tpackage_option_file: \"x/kama_partial.yaml\"",
		},
		{
			name: "package option file of another package",
			opts: Options{Loaded: &LoadedOptions{
				PackageFiles: map[string]string{"example.invalid/other": "other/kama_partial.yaml"},
			}},
			params: "//\tmerge: \"overwrite\"\n//\tmerge_nested: \"recursive\"\n" +
				"//\toption_file: null\n//\tpackage_option_file: null",
		},
		{
			name: "quoted",
			opts: Options{Loaded: &LoadedOptions{Files: []string{"my \"opts\".yaml"}}},
			params: "//\tmerge: \"overwrite\"\n//\tmerge_nested: \"recursive\"\n" +
				"//\toption_file: \"my \\\"opts\\\".yaml\"\n//\tpackage_option_file: null",
		},
		{
			name: "several option files",
			opts: Options{Loaded: &LoadedOptions{Files: []string{"a.yaml", "b.yaml"}}},
			params: "//\tmerge: \"overwrite\"\n//\tmerge_nested: \"recursive\"\n" +
				"//\toption_file: [\"a.yaml\",\"b.yaml\"]\n//\tpackage_option_file: null",
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			hdr, err := fileHeader(c.opts.WithDefaults(), "example.invalid/x", now)
			assert.NilError(t, err)
			assert.Equal(t, strings.Join(hdr, "\n"), header+"\n// params:\n"+
				c.params+"\n// generated: 2026-11-04T10:12:33Z")
		})
	}
}

func TestGenerateNow(t *testing.T) {
	files := generatedWith(t, map[string]string{
		"a.go": "package x\n\n//kama:partial\ntype A struct{ X int }\n",
	}, Options{Now: func() time.Time { return time.Date(2030, 1, 2, 3, 4, 5, 0, time.UTC) }})
	assert.Equal(t, len(files), 2)

	for name, src := range files {
		assert.Assert(
			t,
			strings.Contains(src, "\n// generated: 2030-01-02T03:04:05Z\n\npackage x\n"),
			name,
		)
	}
}

func TestSameExceptGenerated(t *testing.T) {
	src := map[string]string{"a.go": "package x\n\n//kama:partial\ntype A struct{ X int }\n"}
	at := func(sec int) map[string]string {
		return generatedWith(t, src, Options{
			Now: func() time.Time { return time.Date(2030, 1, 2, 3, 4, sec, 0, time.UTC) },
		})
	}
	a, b := at(5), at(6)
	assert.Equal(t, len(a), 2)

	for name := range a {
		assert.Assert(t, a[name] != b[name], name)
		assert.Assert(t, genhelper.SameExceptGenerated([]byte(a[name]), []byte(b[name])), name)
	}
}

// staleSources hold a target A and the partial file an earlier run gave B,
// a type no longer marked.
var staleSources = map[string]string{
	"a.go": "package x\n\n//kama:partial\ntype A struct{ X int }\n",
	"b.go": "package x\n\ntype B struct{ X int }\n",
	"b.kama_partial.go": header + "\n\npackage x\n\n" +
		"// BPartial is the partial variant of B.\n//\n//kama:generated kama:partial\n" +
		"type BPartial struct{ X int }\n",
}

func TestStale(t *testing.T) {
	_, warnings, err := Generate(gentest.Load(t, staleSources), Options{Registry: registry(t)})
	assert.NilError(t, err)
	assert.Equal(t, len(warnings), 1, "%v", warnings)
	assert.ErrorIs(t, warnings[0], ErrStale)
	assert.ErrorContains(
		t,
		warnings[0],
		"generator/partial/testdata/inline/TestStale/b.kama_partial.go was generated by kama:partial"+
			" but not produced by this run",
	)
}

func TestStaleNone(t *testing.T) {
	reg := registry(t)
	assert.NilError(t, reg.Register("other"))
	_, warnings, err := Generate(gentest.Load(t, map[string]string{
		"a.go": staleSources["a.go"],
		// A file marked by another generator is not this generator's.
		"c.go": "package x\n\n//kama:generated other\ntype C struct{}\n",
	}), Options{Registry: reg})
	assert.NilError(t, err)
	assert.Equal(t, len(warnings), 0, "%v", warnings)
}

// TestStaleHelpersFile reports the helpers file of a package whose partial
// files call no helper.
func TestStaleHelpersFile(t *testing.T) {
	_, warnings, err := Generate(gentest.Load(t, map[string]string{
		"a.go": staleSources["a.go"],
		HelpersFile: "package x\n\n//kama:generated kama:partial\n" +
			"func kamaPartialFromValue() {}\n",
	}), Options{Registry: registry(t)})
	assert.NilError(t, err)
	assert.Equal(t, len(warnings), 1, "%v", warnings)
	assert.ErrorIs(t, warnings[0], ErrStale)
	assert.ErrorContains(t, warnings[0], "/"+HelpersFile+" was generated by kama:partial")
}

func TestStaleKeepsFlagSetOfPackageWithoutOutput(t *testing.T) {
	support := generated(t, map[string]string{"a.go": staleSources["a.go"]})

	cases := []struct {
		name  string
		files map[string]string
	}{
		{
			// The only target is in a build variant the load excludes.
			name: "build tag",
			files: map[string]string{
				"a.go": "//go:build kama_partial_unset\n\n" + staleSources["a.go"],
				"b.go": staleSources["b.go"],
			},
		},
		{
			name: "unmarked",
			files: map[string]string{
				"a.go": "package x\n\ntype A struct{ X int }\n",
				"b.go": staleSources["b.go"],
			},
		},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			c.files["b.kama_partial.go"] = staleSources["b.kama_partial.go"]
			c.files[FlagSetFile] = support[FlagSetFile]
			files, warnings, err := Generate(
				gentest.Load(t, c.files),
				Options{Registry: registry(t)},
			)
			assert.NilError(t, err)
			assert.Equal(t, len(files), 0)
			assert.Equal(t, len(warnings), 1, "%v", warnings)
			assert.ErrorIs(t, warnings[0], ErrStale)
			assert.ErrorContains(t, warnings[0], "/b.kama_partial.go was generated by kama:partial")
		})
	}
}

// procEnv stages files under the inline test directory of t and runs Proc
// against them.
type procEnv struct {
	t   *testing.T
	f   *overlayfs.Fs
	dir string
}

func newProcEnv(t *testing.T, files map[string]string, opts ...overlayfs.Option) *procEnv {
	t.Helper()

	f, err := overlayfs.New(".", opts...)
	assert.NilError(t, err)
	t.Cleanup(func() { f.Close() })

	e := &procEnv{t: t, f: f, dir: "testdata/inline/" + strings.ReplaceAll(t.Name(), "/", "_")}
	for name, src := range files {
		e.write(name, src)
	}

	return e
}

func (e *procEnv) write(name, src string) {
	e.t.Helper()
	assert.NilError(e.t, e.f.Write(context.Background(), path.Join(e.dir, name), []byte(src)))
}

func (e *procEnv) read(name string) string {
	e.t.Helper()
	b, err := fs.ReadFile(e.f.FS(), path.Join(e.dir, name))
	assert.NilError(e.t, err)

	return string(b)
}

// run loads the packages, staged files included, and runs Proc with now.
func (e *procEnv) run(now time.Time) *gentest.RecordReporter {
	e.t.Helper()

	ctx := context.Background()
	pkgs, err := gopackages.Load(ctx, e.f, gopackages.Options{Patterns: []string{"./" + e.dir}})
	assert.NilError(e.t, err)

	i := &instance{}
	assert.NilError(e.t, i.Param(ProcParamPartial{}))
	i.opts.Registry = registry(e.t)
	i.opts.Now = func() time.Time { return now }
	i.In(&procgopackages.Packages{Pkgs: pkgs})
	i.Out(e.f)

	r := &gentest.RecordReporter{}
	assert.NilError(e.t, i.Run(ctx, r))

	return r
}

func TestProcStale(t *testing.T) {
	e := newProcEnv(t, staleSources)
	r := e.run(time.Date(2026, 11, 4, 10, 12, 33, 0, time.UTC))
	assert.Equal(t, len(r.Warnings), 1, "%v", r.Warnings)
	assert.Assert(t, errors.Is(r.Warnings[0], ErrStale))
	assert.ErrorContains(t, r.Warnings[0], "b.kama_partial.go")
	assert.DeepEqual(t, r.Messages, []string{"2 files written, 0 files unchanged"})
	// The stale file is left in place.
	assert.Equal(t, e.read("b.kama_partial.go"), staleSources["b.kama_partial.go"])
}

func TestProcKeepsUnchanged(t *testing.T) {
	const (
		first  = "// generated: 2026-11-04T10:12:33Z\n"
		second = "// generated: 2026-11-05T00:00:00Z\n"
		third  = "// generated: 2026-11-06T00:00:00Z\n"
	)

	e := newProcEnv(t, map[string]string{"a.go": staleSources["a.go"]})
	r := e.run(time.Date(2026, 11, 4, 10, 12, 33, 0, time.UTC))
	assert.DeepEqual(t, r.Messages, []string{"2 files written, 0 files unchanged"})

	names := []string{"a.kama_partial.go", FlagSetFile}

	before := map[string]string{}
	for _, name := range names {
		before[name] = e.read(name)
		assert.Assert(t, strings.Contains(before[name], first), name)
	}

	r = e.run(time.Date(2026, 11, 5, 0, 0, 0, 0, time.UTC))
	assert.Equal(t, len(r.Warnings), 0, "%v", r.Warnings)
	assert.DeepEqual(t, r.Messages, []string{"0 files written, 2 files unchanged"})

	for _, name := range names {
		assert.Equal(t, e.read(name), before[name], name)
	}

	e.write("a.go", "package x\n\n//kama:partial\ntype A struct{ X, Y int }\n")
	r = e.run(time.Date(2026, 11, 6, 0, 0, 0, 0, time.UTC))
	assert.DeepEqual(t, r.Messages, []string{"1 file written, 1 file unchanged"})

	got := map[string]string{}
	for _, name := range names {
		got[name] = e.read(name)
	}

	assert.Assert(t, strings.Contains(got["a.kama_partial.go"], third))
	assert.Assert(t, strings.Contains(got["a.kama_partial.go"], "Y und.Und[int]"))
	assert.Assert(t, !strings.Contains(got["a.kama_partial.go"], second))
	delete(got, "a.kama_partial.go")
	delete(before, "a.kama_partial.go")
	assert.DeepEqual(t, slices.Sorted(maps.Keys(got)), slices.Sorted(maps.Keys(before)))
	assert.DeepEqual(t, got, before)
}

// prefixFormatter prepends a line to every file it formats, so formatting
// a file twice is visible. It writes its result into src's storage, as a
// formatter may, so a caller reusing src after formatting would see it.
type prefixFormatter struct{}

const formattedPrefix = "// formatted\n"

func (prefixFormatter) Format(_ context.Context, _ string, src []byte) ([]byte, error) {
	prefixed := append([]byte(formattedPrefix), src...)
	return append(src[:0], prefixed...), nil
}

func TestProcKeepsUnchangedNonIdempotentFormatter(t *testing.T) {
	e := newProcEnv(
		t,
		map[string]string{"a.go": staleSources["a.go"]},
		overlayfs.WithFormatter(prefixFormatter{}),
	)
	names := []string{"a.kama_partial.go", FlagSetFile}
	singlePrefix := func(name, src string) {
		t.Helper()
		assert.Assert(t, strings.HasPrefix(src, formattedPrefix), name)
		assert.Assert(t, !strings.HasPrefix(src, formattedPrefix+formattedPrefix), name)
	}

	r := e.run(time.Date(2026, 11, 4, 10, 12, 33, 0, time.UTC))
	assert.DeepEqual(t, r.Messages, []string{"2 files written, 0 files unchanged"})

	before := map[string]string{}
	for _, name := range names {
		before[name] = e.read(name)
		singlePrefix(name, before[name])
	}

	r = e.run(time.Date(2026, 11, 5, 0, 0, 0, 0, time.UTC))
	assert.DeepEqual(t, r.Messages, []string{"0 files written, 2 files unchanged"})

	for _, name := range names {
		assert.Equal(t, e.read(name), before[name], name)
	}

	e.write("a.go", "package x\n\n//kama:partial\ntype A struct{ X, Y int }\n")
	r = e.run(time.Date(2026, 11, 6, 0, 0, 0, 0, time.UTC))
	assert.DeepEqual(t, r.Messages, []string{"1 file written, 1 file unchanged"})

	got := e.read("a.kama_partial.go")
	singlePrefix("a.kama_partial.go", got)
	assert.Assert(t, strings.Contains(got, "// generated: 2026-11-06T00:00:00Z\n"))
	assert.Assert(t, strings.Contains(got, "Y und.Und[int]"))

	for _, name := range names[1:] {
		assert.Equal(t, e.read(name), before[name], name)
	}
}
